@test
def test_sobol():
    assert close(qmc.Sobol(3, scramble=False).random(8), sob_u)
    assert close(qmc.Sobol(3, rng=7).random(8), sob_s)
    s = qmc.Sobol(5, rng=np.random.default_rng(11))
    s.random(4)
    assert close(s.random(4), sob_s2)
    assert close(qmc.Sobol(2, rng=3, bits=40).random_base2(3), sob_b)
    s2 = qmc.Sobol(2, rng=3)
    s2.fast_forward(5)
    assert close(s2.random(3), sob_ff)
    assert close(qmc.Sobol(40, rng=1).random(4), sob_hd)
    assert close(qmc.Sobol(2, rng=4).integers(10, n=4).astype(float), ints)
test_sobol()

@test
def test_halton_lhs_disc():
    assert close(qmc.Halton(3, scramble=False).random(6), hal_u)
    assert close(qmc.Halton(4, rng=5).random(6), hal_s)
    assert close(qmc.LatinHypercube(3, rng=2).random(5), lhs)
    assert close(qmc.LatinHypercube(2, rng=2, scramble=False).random(4), lhs_c)
    smp = qmc.Halton(3, scramble=False).random(10)[1:]
    d0 = qmc.discrepancy(smp)
    got = [qmc.discrepancy(smp, method='CD'), qmc.discrepancy(smp, method='WD'),
           qmc.discrepancy(smp, method='MD'), qmc.discrepancy(smp, method='L2-star'),
           qmc.discrepancy(smp, iterative=True),
           qmc.update_discrepancy(np.array([0.3, 0.6, 0.1]), smp, d0)]
    assert close(got, disc)
    sc = qmc.scale(smp[:3], [-1, 0, 2], [1, 5, 3])
    assert close(sc, scl)
    assert close(qmc.scale(sc, [-1, 0, 2], [1, 5, 3], reverse=True), scl_r)
    assert close(qmc.van_der_corput(7, 3, start_index=2), vdc)
test_halton_lhs_disc()
